// ESLint flat config: Instea code quality checks (TS/JS).
// Generated by /project-setup:create-code-quality-checks. See docs/code-quality.md.
// Migrated from the legacy .eslintrc ("extends": "react-app" + semi/quotes/indent rules).
import { fixupPluginRules } from '@eslint/compat';
import js from '@eslint/js';
import { defineConfig, globalIgnores } from 'eslint/config';
import prettier from 'eslint-config-prettier/flat';
import react from 'eslint-plugin-react';
import reactHooks from 'eslint-plugin-react-hooks';
import sonarjs from 'eslint-plugin-sonarjs';
import unicorn from 'eslint-plugin-unicorn';
import globals from 'globals';
import tseslint from 'typescript-eslint';

// One severity for every rule: "error" fails the check, "warn" only reports.
const SEVERITY = 'warn';

// Rewrites every rule set to "error"/2 (string or array form) to `severity`.
// "off"/"warn" stay as they are, so preset rules follow SEVERITY too.
function withSeverity(configs, severity) {
  const isError = (level) => level === 'error' || level === 2;
  return configs.map((config) => {
    if (!config.rules) return config;
    const rules = Object.fromEntries(
      Object.entries(config.rules).map(([name, value]) => {
        if (Array.isArray(value) && isError(value[0]))
          return [name, [severity, ...value.slice(1)]];
        if (isError(value)) return [name, severity];
        return [name, value];
      })
    );
    return { ...config, rules };
  });
}

export default withSeverity(
  defineConfig([
    globalIgnores(['**/dist/', '**/build/', '**/coverage/']),
    js.configs.recommended,
    tseslint.configs.recommendedTypeChecked,
    {
      languageOptions: {
        globals: {
          ...globals.node,
          ...globals.browser,
          ...globals.jest,
          ...globals.jasmine,
        },
        parserOptions: {
          projectService: true,
          tsconfigRootDir: import.meta.dirname,
          ecmaFeatures: { jsx: true },
        },
      },
    },
    // Angular 4 sources: TypeScript 6 rejects angular/tsconfig.json options, so ESLint uses a
    // dedicated tsconfig that Angular's own TypeScript 2.3 never reads.
    {
      files: ['angular/**/*.ts'],
      languageOptions: {
        parserOptions: {
          projectService: false,
          project: ['./angular/tsconfig.eslint.json'],
        },
      },
    },
    // Type-aware rules need a tsconfig; plain JS files (configs, scripts) skip them.
    {
      files: ['**/*.{js,mjs,cjs,jsx}'],
      extends: [tseslint.configs.disableTypeChecked],
    },
    sonarjs.configs.recommended,
    {
      plugins: { unicorn },
      rules: {
        // Curated, low-noise subset. Rationale in references/typescript.md.
        'unicorn/error-message': SEVERITY,
        'unicorn/no-array-push-push': SEVERITY,
        'unicorn/no-instanceof-builtins': SEVERITY,
        'unicorn/no-lonely-if': SEVERITY,
        'unicorn/no-new-array': SEVERITY,
        'unicorn/no-typeof-undefined': SEVERITY,
        'unicorn/no-unnecessary-await': SEVERITY,
        'unicorn/no-useless-spread': SEVERITY,
        'unicorn/prefer-array-find': SEVERITY,
        'unicorn/prefer-array-some': SEVERITY,
        'unicorn/prefer-date-now': SEVERITY,
        'unicorn/prefer-includes': SEVERITY,
        'unicorn/prefer-node-protocol': SEVERITY,
        'unicorn/prefer-string-starts-ends-with': SEVERITY,
        'unicorn/throw-new-error': SEVERITY,
      },
    },
    {
      rules: {
        complexity: [SEVERITY, 10],
        'max-depth': [SEVERITY, 4],
        'max-params': [SEVERITY, 4],
        'max-lines-per-function': [
          SEVERITY,
          { max: 80, skipBlankLines: true, skipComments: true },
        ],
        'max-nested-callbacks': [SEVERITY, 3],
        'sonarjs/cognitive-complexity': [SEVERITY, 15],
        'no-unreachable': SEVERITY,
        'no-unused-private-class-members': SEVERITY,
        // File-level size and expression complexity.
        'max-lines': [
          SEVERITY,
          { max: 300, skipBlankLines: true, skipComments: true },
        ],
        'sonarjs/expression-complexity': [SEVERITY, { max: 3 }],
        // DRY: repeated string literals and duplicate imports.
        'sonarjs/no-duplicate-string': [SEVERITY, { threshold: 3 }],
        'no-duplicate-imports': SEVERITY,
      },
    },
    // --- React (eslint-plugin-react + eslint-plugin-react-hooks) ---------------------------
    // Replaces the legacy "react-app" preset. React 16 uses the classic JSX runtime.
    // fixupPluginRules: eslint-plugin-react 7 still calls context APIs removed in ESLint 10.
    {
      files: ['src/**/*.{js,jsx}'],
      ...react.configs.flat.recommended,
      plugins: { react: fixupPluginRules(react) },
      settings: { react: { version: 'detect' } },
    },
    reactHooks.configs.flat.recommended,

    // Must stay last before the user rules: turns off rules that conflict with Prettier.
    prettier,

    // User rules from the legacy .eslintrc. They win over eslint-config-prettier.
    {
      rules: {
        semi: 2,
        quotes: ['error', 'single', { avoidEscape: true }],
        indent: ['error', 2],
      },
    },
  ]),
  SEVERITY
);
